import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import '../api/api_client.dart'    class SvetlanaScreen extends ConsumerStatefulWidget {    const SvetlanaScreen({super.key})      @override    ConsumerState<SvetlanaScreen> createState() => _SvetlanaScreenState()  }    class _SvetlanaScreenState extends ConsumerState<SvetlanaScreen> {    final List<Map<String, dynamic>> _messages = []    final _controller = TextEditingController()    final _scrollController = ScrollController()    bool _isLoading = false      @override    void initState() {      super.initState()      _messages.add({        'role': 'assistant',        'text': 'Привет! Я Светлана — ваш AI-ассистент. Чем могу помочь сегодня?',        'time': DateTime.now(),      })    }      Future<void> _sendMessage() async {      final text = _controller.text.trim()      if (text.isEmpty) return        setState(() {        _messages.add({'role': 'user', 'text': text, 'time': DateTime.now()})        _isLoading = true        _controller.clear()      })        _scrollToBottom()        try {        // TODO: интеграция с OpenRouter API        await Future.delayed(const Duration(seconds: 1))        setState(() {          _messages.add({            'role': 'assistant',            'text': 'Я пока в режиме демо. Полная интеграция с OpenRouter будет в v8.7.',            'time': DateTime.now(),          })          _isLoading = false        })      } catch (e) {        setState(() {          _messages.add({            'role': 'assistant',            'text': 'Извините, произошла ошибка. Попробуйте позже.',            'time': DateTime.now(),          })          _isLoading = false        })      }        _scrollToBottom()    }      void _scrollToBottom() {      Future.delayed(const Duration(milliseconds: 100), () {        if (_scrollController.hasClients) {          _scrollController.animateTo(            _scrollController.position.maxScrollExtent,            duration: const Duration(milliseconds: 300),            curve: Curves.easeOut,          )        }      })    }      @override    Widget build(BuildContext context) {      return Scaffold(        appBar: AppBar(          title: Row(            children: [              Container(                width: 8,                height: 8,                decoration: const BoxDecoration(                  color: Colors.green,                  shape: BoxShape.circle,                ),              ),              const SizedBox(width: 8),              const Text('Светлана AI'),            ],          ),          actions: [            IconButton(              icon: const Icon(Icons.more_vert),              onPressed: () {},            ),          ],        ),        body: Column(          children: [            // Messages            Expanded(              child: ListView.builder(                controller: _scrollController,                padding: const EdgeInsets.all(16),                itemCount: _messages.length,                itemBuilder: (context, index) {                  final msg = _messages[index]                  final isUser = msg['role'] == 'user'                    return Align(                    alignment: isUser ? Alignment.centerRight : Alignment.centerLeft,                    child: Container(                      constraints: BoxConstraints(                        maxWidth: MediaQuery.of(context).size.width * 0.75,                      ),                      margin: const EdgeInsets.only(bottom: 12),                      padding: const EdgeInsets.all(14),                      decoration: BoxDecoration(                        color: isUser                          ? Theme.of(context).colorScheme.primary                          : Colors.grey[100],                        borderRadius: BorderRadius.only(                          topLeft: const Radius.circular(16),                          topRight: const Radius.circular(16),                          bottomLeft: Radius.circular(isUser ? 16 : 4),                          bottomRight: Radius.circular(isUser ? 4 : 16),                        ),                      ),                      child: Column(                        crossAxisAlignment: CrossAxisAlignment.start,                        children: [                          Text(                            msg['text'],                            style: TextStyle(                              color: isUser ? Colors.white : Colors.black87,                              fontSize: 15,                            ),                          ),                          const SizedBox(height: 4),                          Text(                            '${(msg['time'] as DateTime).hour.toString().padLeft(2, '0')}:${(msg['time'] as DateTime).minute.toString().padLeft(2, '0')}',                            style: TextStyle(                              fontSize: 10,                              color: isUser ? Colors.white70 : Colors.grey[500],                            ),                          ),                        ],                      ),                    ),                  )                },              ),            ),              // Quick actions            Container(              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),              child: SingleChildScrollView(                scrollDirection: Axis.horizontal,                child: Row(                  children: [                    _QuickChip(label: 'Создать счет', onTap: () {}),                    _QuickChip(label: 'Новый клиент', onTap: () {}),                    _QuickChip(label: 'Расчет налогов', onTap: () {}),                    _QuickChip(label: 'Статистика', onTap: () {}),                  ],                ),              ),            ),              // Input            Container(              padding: const EdgeInsets.all(12),              decoration: BoxDecoration(                color: Colors.white,                border: Border(top: BorderSide(color: Colors.grey[200]!)),              ),              child: SafeArea(                child: Row(                  children: [                    IconButton(                      icon: const Icon(Icons.attach_file),                      onPressed: () {},                    ),                    Expanded(                      child: TextField(                        controller: _controller,                        decoration: InputDecoration(                          hintText: 'Напишите сообщение...',                          filled: true,                          fillColor: Colors.grey[100],                          border: OutlineInputBorder(                            borderRadius: BorderRadius.circular(24),                            borderSide: BorderSide.none,                          ),                          contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),                        ),                        onSubmitted: (_) => _sendMessage(),                      ),                    ),                    const SizedBox(width: 8),                    _isLoading                      ? const SizedBox(                          height: 24,                          width: 24,                          child: CircularProgressIndicator(strokeWidth: 2),                        )                      : IconButton(                          icon: const Icon(Icons.send),                          color: Theme.of(context).colorScheme.primary,                          onPressed: _sendMessage,                        ),                  ],                ),              ),            ),          ],        ),      )    }  }    class _QuickChip extends StatelessWidget {    final String label    final VoidCallback onTap      const _QuickChip({required this.label, required this.onTap})      @override    Widget build(BuildContext context) {      return Padding(        padding: const EdgeInsets.only(right: 8),        child: ActionChip(          label: Text(label, style: const TextStyle(fontSize: 12)),          backgroundColor: Colors.grey[100],          side: BorderSide(color: Colors.grey[300]!),          onPressed: onTap,        ),      )    }  }